 if(members.some(e=>e.errors.length||e.hts.slice(0,8)!==entry.hts.slice(0,8)))issues.push('Each component group must use one declared eight-digit article classification, with valid entry lines.');
 if(JSON.stringify(expected)!==JSON.stringify(actual))issues.push('Report each published component suffix exactly once, including quantity/value zero for absent components. Required suffixes: '+expected.join(', ')+'.');
 if(members.some(e=>e.shipment?.articleValue!==total))issues.push('All component lines must declare the same complete article value.');
