 for(const e of members){const q=primaryShipmentQuantity(e);if(q.quantity===null||q.unit.toLowerCase()!=='no')issues.push('Each reported component needs its own count in NO, including an explicit zero for absent components.');else if(!normalizedQuantity(q.quantity).endsWith('.'))issues.push('Component counts in NO must be whole nonnegative numbers; no fractional count is rounded.');else if(normalizedQuantity(q.quantity)==='0.'&&e.value!==null&&cents(e.value)!==0n)issues.push('A zero-quantity absent component must also have zero customs value.');}
 for(const e of members){const q=primaryShipmentQuantity(e),reported=[q,{quantity:e.shipment?.quantity2??null,unit:e.shipment?.unit2??''},{quantity:e.shipment?.quantity3??null,unit:e.shipment?.unit3??''}].filter(v=>v.quantity!==null&&v.unit.toLowerCase()==='no');if(new Set(reported.map(v=>normalizedQuantity(v.quantity!))).size>1)issues.push('Conflicting NO quantities on the same component line need reconciliation.');}
