 return{issues:[...new Set(issues)],...(!issues.length?{reconciliation:{group,articleValue:total,componentValueSum:dollars(sum),memberRows:members.map(e=>e.row).sort((a,b)=>a-b),suffixes:expected,note:'Statistical Note 1 requires separate values, every named component (zero quantity/value when absent), and a total equal to the whole article. Declared classification, origin and valuation remain assumptions.'}}:{})};
